content.css:
@font-face {
  font-family: 'Plus Jakarta Sans';
  font-style: normal;
  font-weight: 200 800;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2-variations');
}
.barras-olist-root {
  display: flex;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  overflow: hidden;
  font-weight: 400;
  font-variation-settings: "wght" 400;
  --ds-color-ink: #131B33;
  --ds-color-ink-soft: #4C5378;
  --ds-color-surface: #FFFFFF;
  --ds-color-surface-sunken: #F4F6FC;
  --ds-color-line: #DDE2F0;
  --ds-color-line-soft: #E9ECF6;
  --ds-radius-lg: 28px;
  --ds-shadow-card: 0 1px 2px rgba(19, 27, 51, 0.04), 0 8px 24px -12px rgba(19, 27, 51, 0.18);
  background-color: var(--ds-color-surface);
  border: 1px solid var(--ds-color-line);
  border-radius: var(--ds-radius-lg);
  box-shadow: var(--ds-shadow-card);
  color: var(--ds-color-ink);
}
.chart-title {
  flex: 0 0 auto;
  padding: 14px 16px 0;
  font-family: inherit;
  font-size: 1.2rem;
  line-height: 1.3;
  font-weight: 800;
  font-variation-settings: "wght" 800;
  letter-spacing: -0.01em;
  color: var(--ds-color-ink);
}
.chart-body {
  display: flex;
  flex: 1 1 auto;
  min-height: 0;
  width: 100%;
}
.chart-area {
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  position: relative;
  scrollbar-width: thin;
  scrollbar-color: var(--ds-color-line) transparent;
}
.chart-area::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}
.chart-area::-webkit-scrollbar-track {
  background: transparent;
}
.chart-area::-webkit-scrollbar-thumb {
  background-color: var(--ds-color-line);
  border-radius: 999px;
  border: 2px solid transparent;
  background-clip: padding-box;
}
.chart-scroll-wrapper {
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  scrollbar-width: thin;
  scrollbar-color: var(--ds-color-line) transparent;
}
.chart-scroll-wrapper::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}
.chart-scroll-wrapper::-webkit-scrollbar-track {
  background: transparent;
}
.chart-scroll-wrapper::-webkit-scrollbar-thumb {
  background-color: var(--ds-color-line);
  border-radius: 999px;
  border: 2px solid transparent;
  background-clip: padding-box;
}
.chart-axis-pane {
  flex: 0 0 auto;
}
.barras-olist-svg,
.barras-olist-axis-svg {
  display: block;
}
.category-axis-level text {
  fill: var(--ds-color-ink-soft);
}
.category-axis-divider {
  stroke: var(--ds-color-line);
  stroke-width: 1;
}
.category-axis path.domain,
.value-axis path.domain,
.category-axis line,
.value-axis line {
  stroke: var(--ds-color-line);
  shape-rendering: crispEdges;
}
.category-axis text,
.value-axis text {
  fill: var(--ds-color-ink-soft);
}
.grid-lines line {
  stroke: var(--ds-color-line-soft);
  stroke-width: 1;
  shape-rendering: crispEdges;
}
.zero-baseline {
  stroke: var(--ds-color-line);
  stroke-width: 1;
  shape-rendering: crispEdges;
}
.bar-item {
  cursor: pointer;
  transition: opacity 0.1s ease-in-out;
}
.bar-item:focus-visible {
  outline: 2px solid #0A4EE4;
  outline-offset: 2px;
}
.reference-line {
  stroke: #B9700A;
  stroke-width: 1.5px;
  stroke-dasharray: 5 3;
}
.bar-track {
  fill: var(--ds-color-line-soft);
}
.reference-line-label {
  font-size: 10px;
  font-weight: 700;
  font-variation-settings: "wght" 700;
}
.data-labels {
  pointer-events: none;
}
.data-labels text {
  font-weight: 700;
  font-variation-settings: "wght" 700;
  fill: var(--ds-color-ink);
}
.chart-legend {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
  padding: 8px 12px;
  flex: 0 0 auto;
  box-sizing: border-box;
}
.chart-legend.legend-right {
  flex-direction: column;
  align-items: flex-start;
  width: 140px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--ds-color-line) transparent;
}
.chart-legend.legend-right::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}
.chart-legend.legend-right::-webkit-scrollbar-track {
  background: transparent;
}
.chart-legend.legend-right::-webkit-scrollbar-thumb {
  background-color: var(--ds-color-line);
  border-radius: 999px;
  border: 2px solid transparent;
  background-clip: padding-box;
}
.legend-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 600;
  font-variation-settings: "wght" 600;
  color: var(--ds-color-ink);
  cursor: pointer;
}
.legend-item:focus-visible {
  outline: 2px solid #0A4EE4;
  outline-offset: 2px;
}
.legend-item.legend-item-hidden {
  opacity: 0.4;
}
.legend-item.legend-item-hidden .legend-label {
  text-decoration: line-through;
}
.legend-swatch {
  width: 10px;
  height: 10px;
  border-radius: 3px;
  flex: 0 0 auto;
}
.legend-swatch-line {
  width: 14px;
  height: 0;
  border-radius: 0;
  border-top: 2px solid;
}
.line-area {
  opacity: 0.12;
  pointer-events: none;
}
.line-path {
  stroke-width: 2.5px;
  stroke-linecap: round;
  stroke-linejoin: round;
  fill: none;
}
.line-point-ring,
.line-point-dot {
  pointer-events: none;
}
.line-point {
  cursor: pointer;
}
.line-point:focus-visible .line-point-dot {
  stroke: var(--ds-color-ink);
  stroke-width: 2px;
}
.value-axis-secondary path.domain,
.value-axis-secondary line {
  stroke: var(--ds-color-line);
}
.value-axis-secondary text {
  fill: var(--ds-color-ink-soft);
}
.empty-state {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: var(--ds-color-ink-soft);
  font-size: 13px;
  text-align: center;
  padding: 16px;
  box-sizing: border-box;
}
.chart-skeleton {
  display: flex;
  align-items: flex-end;
  justify-content: space-around;
  width: 100%;
  height: 100%;
  padding: 24px;
  box-sizing: border-box;
  gap: 8px;
}
.skeleton-bar {
  flex: 1 1 auto;
  max-width: 40px;
  border-radius: 6px 6px 0 0;
  background: linear-gradient(90deg, var(--ds-color-line-soft) 25%, var(--ds-color-surface-sunken) 50%, var(--ds-color-line-soft) 75%);
  background-size: 200% 100%;
  animation: skeleton-shimmer 1.4s ease-in-out infinite;
}
@keyframes skeleton-shimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}
.high-contrast {
  box-shadow: none !important;
}
.high-contrast .category-axis path.domain,
.high-contrast .value-axis path.domain,
.high-contrast .category-axis line,
.high-contrast .value-axis line {
  stroke: currentColor !important;
}
.high-contrast .category-axis text,
.high-contrast .value-axis text {
  fill: currentColor !important;
}
.high-contrast .grid-lines line {
  stroke: currentColor !important;
  opacity: 0.3;
}
.high-contrast .zero-baseline {
  stroke: currentColor !important;
}
.high-contrast .bar-label {
  fill: currentColor !important;
}
.high-contrast .legend-swatch {
  border: 1px solid currentColor;
}
.high-contrast .line-area {
  display: none;
}
.high-contrast .line-point-ring {
  fill: none !important;
}
.high-contrast .bar-track {
  fill: none !important;
  stroke: currentColor !important;
  opacity: 0.4;
}
.custom-tooltip {
  position: fixed;
  z-index: 999999;
  pointer-events: none;
  font-size: 12px;
  min-width: 140px;
  max-width: 280px;
  border-radius: 18px;
  padding: 10px 14px;
  --ds-color-ink: #131B33;
  --ds-color-ink-soft: #4C5378;
  --ds-color-surface: #FFFFFF;
  --ds-color-line: #DDE2F0;
  --ds-color-line-soft: #E9ECF6;
  --ds-shadow-card: 0 1px 2px rgba(19, 27, 51, 0.04), 0 8px 24px -12px rgba(19, 27, 51, 0.18);
  box-shadow: var(--ds-shadow-card);
  background-color: var(--ds-color-surface);
  color: var(--ds-color-ink);
  border: 1px solid var(--ds-color-line);
  border-top: 3px solid #0A4EE4;
}
.custom-tooltip .tooltip-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  padding: 3px 0;
}
.custom-tooltip .tooltip-row + .tooltip-row {
  border-top: 1px solid var(--ds-color-line-soft);
}
.custom-tooltip .tooltip-label {
  font-weight: 700;
  font-variation-settings: "wght" 700;
  text-transform: uppercase;
  font-size: 10px;
  letter-spacing: 0.06em;
  color: var(--ds-color-ink-soft);
  white-space: nowrap;
}
.custom-tooltip .tooltip-value {
  text-align: right;
  white-space: nowrap;
  font-weight: 600;
  font-variation-settings: "wght" 600;
}
